// ---------------------------------------------------------------------------
// decimal: an exact value `n * 10^-s`, parsed from `-?\d+(\.\d+)?`
// ---------------------------------------------------------------------------

export interface Decimal {
  readonly n: bigint;
  readonly s: number;
}

const RE_DEC = /^(-?)(\d+)(?:\.(\d+))?$/;

/** Parses a wire decimal (or a decimal literal). */
export function dec(text: string | number): Decimal {
  const m = RE_DEC.exec(String(text));
  if (m === null) throw new TypeError(`invalid decimal: ${String(text)}`);
  const frac = m[3] ?? '';
  return { n: BigInt(`${m[1] ?? ''}${m[2] ?? ''}${frac}`), s: frac.length };
}

export function decFromInt(n: number): Decimal {
  return { n: BigInt(n), s: 0 };
}

export function decFromLong(n: bigint): Decimal {
  return { n, s: 0 };
}

function atScale(d: Decimal, s: number): bigint {
  return d.s === s ? d.n : d.n * 10n ** BigInt(s - d.s);
}

export function decAdd(a: Decimal, b: Decimal): Decimal {
  const s = Math.max(a.s, b.s);
  return { n: atScale(a, s) + atScale(b, s), s };
}

export function decSub(a: Decimal, b: Decimal): Decimal {
  const s = Math.max(a.s, b.s);
  return { n: atScale(a, s) - atScale(b, s), s };
}

export function decMul(a: Decimal, b: Decimal): Decimal {
  return { n: a.n * b.n, s: a.s + b.s };
}

export function decNeg(a: Decimal): Decimal {
  return { n: -a.n, s: a.s };
}

/** Numeric comparison: `1.50` equals `1.5`. Returns a negative number, zero or a positive number. */
export function decCmp(a: Decimal, b: Decimal): number {
  const s = Math.max(a.s, b.s);
  const x = atScale(a, s);
  const y = atScale(b, s);
  return x < y ? -1 : x > y ? 1 : 0;
}

