// ---------------------------------------------------------------------------
// string, uuid, bytes, list, map
// ---------------------------------------------------------------------------

/** The number of Unicode code points (the meaning of `@length` and `len`). */
export function lenString(s: string): number {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

/** The number of bytes that padded base64 text stands for. */
export function lenBytes(text: string): number {
  const pad = text.endsWith('==') ? 2 : text.endsWith('=') ? 1 : 0;
  return inInt((text.length / 4) * 3 - pad);
}

export function lenMap(m: object): number {
  return Object.keys(m).length;
}

export function hasKey(m: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(m, key);
}

/** A uuid in its canonical lower-case form. */
export function toUuid(s: string): string {
  return s.toLowerCase();
}

const patterns = new Map<string, RegExp>();

/** `matches(s, "re")`: the same `RegExp` with the `u` flag that `@pattern` uses, searching anywhere unless anchored. */
export function matches(s: string, pattern: string): boolean {
  let re = patterns.get(pattern);
  if (re === undefined) {
    re = new RegExp(pattern, 'u');
    patterns.set(pattern, re);
  }
  return re.test(s);
}

// ---------------------------------------------------------------------------
// Comprehensions
// ---------------------------------------------------------------------------

/** `count(list, x => bool)`: checked. */
export function countWhere<T>(list: readonly T[], f: (x: T) => boolean): number {
  let n = 0;
  for (const x of list) if (f(x)) n++;
  return inInt(n);
}

export function sumInt<T>(list: readonly T[], f: (x: T) => number): number {
  let acc = 0;
  for (const x of list) acc = addInt(acc, f(x));
  return acc;
}

export function sumLong<T>(list: readonly T[], f: (x: T) => bigint): bigint {
  let acc = 0n;
  for (const x of list) acc = addLong(acc, f(x));
  return acc;
}

export function sumFloat<T>(list: readonly T[], f: (x: T) => number): number {
  let acc = 0;
  for (const x of list) acc = addFloat(acc, f(x));
  return acc;
}

export function sumDecimal<T>(list: readonly T[], f: (x: T) => Decimal): Decimal {
  let acc: Decimal = { n: 0n, s: 0 };
  for (const x of list) acc = decAdd(acc, f(x));
  return acc;
}

/** `x in list` for decimals, which have no native equality. */
export function decIn(x: Decimal, list: readonly Decimal[]): boolean {
  return list.some((y) => decCmp(x, y) === 0);
}
